    b"        control_binding = {'shape': list(controls.shape), 'dtype': controls.dtype.str,\n",
    b"                           'sha256': hashlib.sha256(controls.tobytes()).hexdigest(),\n",
    b"                           'basis': 'staged_control_points'}\n",
    b"        bound_fingerprint = hashlib.sha256(_canonical({'files_fingerprint': context.fingerprint,\n",
    b"            'initializer': context.policy['initializer'], 'actual_control_basis': control_binding})).hexdigest()\n",
    b'        def bound_context():\n',
    b'            context.current()\n',
    b'            model = self.statistical_model\n',
    b"            if getattr(model, 'freeze_template', None) is not True or getattr(model, 'freeze_control_points', None) is not True:\n",
    b"                raise ValueError('Native frozen-model flags changed')\n",
    b'            current = np.asarray(model.get_control_points())\n',
    b'            if (current.dtype != controls.dtype or current.shape != controls.shape\n',
    b'                    or not np.array_equal(current.view(np.uint64), controls.view(np.uint64))):\n',
    b"                raise ValueError('Actual frozen native control basis changed')\n",
    b'            return bound_fingerprint\n',
    b'        bound_context()\n',
    b"        # Keep C5's exact original-method provenance check, while blocking any\n",
    b'        # write on an unguarded/unstarted instance through the class entry gate.\n',
    b'        self.write = types.MethodType(original_write, self)\n',
    b'        try:\n',
    b'            guard = guard_module.attach_instance(\n',
    b"                self, context.root / 'output' / 'numerical-guard',\n",
    b"                provenance={'objective_fingerprint': bound_fingerprint, 'policy': context.policy,\n",
    b"                            'actual_control_basis': control_binding,\n",
    b"                            'native_estimator_source_sha256': NATIVE_SCIPY_SHA,\n",
    b"                            'scope': DECLARATION, 'input_identity_count': len(context.records)},\n",
    b'                context_provider=bound_context)\n',
    b'        except BaseException:\n',
    b"            del self.__dict__['write']\n",
    b'            raise\n',
    b'        c5_write = self.write\n',
    b'\n',
    b'        def verified_write(*a, **k):\n',
    b'            try:\n',
    b'                context.verify_content()\n',
    b'                result = c5_write(*a, **k)\n',
    b'                context.verify_content()\n',
    b'                return result\n',
    b'            except guard_module.NumericalGuardViolation:\n',
    b'                raise\n',
    b'            except BaseException as error:\n',
    b"                guard.fail('verified_native_export_failed', error=type(error).__name__ + ': ' + str(error))\n",
    b'        self.write = verified_write\n',
    b'        try:\n',
    b'            result = original_update(self, *args, **kwargs)\n',
    b'            guard.export_allowed(self._vectorize_parameters(self._get_parameters()))\n',
    b'            return result\n',
    b'        except guard_module.NumericalGuardViolation:\n',
    b'            raise\n',
    b'        except BaseException as error:\n',
    b"            guard.fail('native_update_exception', error=type(error).__name__ + ': ' + str(error))\n",
    b'        finally:\n',
    b'            try:\n',
    b'                context.verify_content()\n',
    b'            except BaseException as error:\n',
    b"                guard.fail('post_update_context_verification_failed', error=type(error).__name__ + ': ' + str(error))\n",
    b'\n',
    b'    def unguarded_write_forbidden(self, *args, **kwargs):\n',
    b"        raise guard_module.NumericalGuardViolation('Native export requires an attached finite accepted guard')\n",
    b'\n',
    b'    native.ScipyOptimize.update = guarded_update\n',
    b'    native.ScipyOptimize.write = unguarded_write_forbidden\n',
    b'    native.ScipyOptimize._df_regional_c5_installed = True\n',
    b'    context.verify_content()\n',
    b'    return context\n',
